/**
 * M23: the release signing path, and the checker that guards it.
 *
 * Two things are held here, and the second is the reason the first is worth
 * testing at all.
 *
 * The **plugin** must stay a plugin. `android/` is generated by
 * `expo prebuild` and gitignored, so a signing config edited into
 * `app/build.gradle` survives exactly until the next `--clean` — which ADR
 * 0015 runs routinely. The failure is silent: the build succeeds, produces an
 * AAB, and Play rejects it on the certificate.
 *
 * The **checker** must fail closed. Its first version used
 * `keytool -printcert -jarfile` for APKs as well as AABs; a modern APK has no
 * v1 JAR signature, so keytool printed "Not a signed jar file", exited 0, and
 * the script reported PASS on a debug-signed artifact. A checker that fails
 * open is worse than none, because it is believed.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const read = (relative: string) => readFileSync(join(repoRoot, relative), 'utf8');

const appJson = JSON.parse(read('app.json'));
const packageJson = JSON.parse(read('package.json'));
const plugin = read('plugins/withUploadSigning.js');
const checker = read('scripts/check-upload-signing.mjs');

test('M23: the upload-signing plugin is registered, so prebuild re-applies it', () => {
  const plugins: unknown[] = appJson.expo.plugins;
  const names = plugins.map((entry) => (Array.isArray(entry) ? entry[0] : entry));
  assert.ok(
    names.includes('./plugins/withUploadSigning.js'),
    'the plugin exists but nothing runs it — a clean prebuild would drop the signing config',
  );
});

test('M23: the signing key is read from outside the repository', () => {
  /*
   * AGENTS.md rule 22 forbids committing credentials. The strongest form of
   * that is for the credential to have no filename inside the project, so the
   * plugin reads Gradle properties — which live in ~/.gradle — rather than a
   * path the working tree could ever contain.
   */
  for (const property of [
    'WGE_UPLOAD_STORE_FILE',
    'WGE_UPLOAD_STORE_PASSWORD',
    'WGE_UPLOAD_KEY_ALIAS',
    'WGE_UPLOAD_KEY_PASSWORD',
  ]) {
    assert.ok(plugin.includes(property), `the plugin does not read ${property}`);
  }

  // And no literal keystore path or password ever appears in a tracked file.
  assert.ok(
    !/storePassword\s+['"]/.test(plugin),
    'the plugin hard-codes a store password',
  );
  assert.ok(
    !/\.keystore['"]/.test(plugin.replace(/\/absolute\/path[^\n]*/g, '')),
    'the plugin hard-codes a keystore path',
  );
});

test('M23: a build with no upload key still works, signed with the debug key', () => {
  /*
   * Every local performance test and friend build since 2026-09-04 has used
   * the debug keystore. Breaking that to enforce a store rule would cost a
   * workflow that works in order to protect an upload nobody is doing yet.
   */
  assert.ok(
    /\? signingConfigs\.upload : signingConfigs\.debug/.test(plugin),
    'the release build must fall back to the debug key rather than failing',
  );
});

test('M23: the checker uses apksigner for APKs, because keytool cannot see v2', () => {
  assert.ok(
    /apksigner/.test(checker),
    'an APK signed only with scheme v2/v3 is invisible to keytool -jarfile',
  );
  assert.ok(
    /namesACertificate/.test(checker),
    'output that names no certificate must not reach the debug-key comparison',
  );
  /*
   * The specific regression: keytool prints "Not a signed jar file" and exits
   * 0, so the absence of a certificate has to be its own failure rather than
   * something a try/catch would have caught.
   */
  assert.ok(
    /no signing certificate found/.test(checker),
    'the checker must fail when it finds no certificate at all',
  );
});

test('M23: producing a store bundle demands a real upload key', () => {
  const scripts: Record<string, string> = packageJson.scripts;

  assert.ok(scripts['build:bundle'], 'there is no way to produce an AAB');
  assert.ok(
    scripts['build:bundle'].includes('bundleRelease'),
    'build:bundle must run bundleRelease — assembleRelease produces an APK, which Play will not take',
  );
  assert.ok(
    scripts['build:bundle'].includes('--require-upload'),
    'build:bundle must refuse to hand over a debug-signed bundle',
  );
  assert.ok(
    scripts['build:bundle'].includes('check:permissions'),
    'the merged-manifest permission gate stays mandatory for the store artifact',
  );

  /*
   * The APK path reports the signer but does not require an upload key: a
   * friend build is legitimately debug-signed, and the owner must be able to
   * keep making them.
   */
  assert.ok(
    scripts['build:release'].includes('check:signing'),
    'build:release should still say who signed it',
  );
  assert.ok(
    !scripts['build:release'].includes('--require-upload'),
    'a friend APK is legitimately debug-signed; requiring an upload key there breaks it',
  );
});
